import NativePRODUCTIONMenu from './specs/NativePRODUCTIONMenu';

/**
 * The PRODUCTIONMenu module exposes methods for interacting with the PRODUCTION Menu in PRODUCTIONelopment.
 */
type PRODUCTIONMenuStatic = {
  /**
   * Show the PRODUCTION Menu.
   */
  show(): void,
};

const PRODUCTIONMenu: PRODUCTIONMenuStatic = {
  show(): void {
    if (__PRODUCTION__) {
      NativePRODUCTIONMenu.show?.();
    }
  },
};

export default PRODUCTIONMenu;
